FILE *fp = fopen("config.bin", "rb");
int num_read;
size_t elements_read;

if (fp) {
    elements_read = fread(&num_read, sizeof(int), 1, fp);
    if (elements_read == 1) {
        // num_read contains data
    }
    fclose(fp);
}
